"use strict";const t=require("../services/api.js");exports.resolveVoicePlaySrc=function(r){const s=(null!=r?r:"").trim();if(!s)return"";if(/^https?:\/\//i.test(s))return s;if(s.startsWith("wxfile://")||s.startsWith("file://")||s.startsWith("http://tmp/")||s.startsWith("https://tmp/")||s.startsWith("blob:"))return s;if(s.startsWith("/")){return`${t.API_BASE_URL.replace(/\/api\/?$/,"")}${s}`}return s};
